<!doctype html>
<html lang="ru">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="robots" content="noindex,nofollow,noarchive">
    <title>{{ $title ?? 'Онлайн-заказ KOTLOV.BY' }}</title>
    <style>
        :root{color-scheme:light;--red:#dc4646;--red-dark:#b63434;--ink:#171717;--muted:#6b7280;--line:#e5e7eb;--soft:#f7f7f8;--ok:#147a45;--warn:#a85f00}*{box-sizing:border-box}body{margin:0;background:#f2f3f5;color:var(--ink);font-family:Inter,Arial,sans-serif;line-height:1.45}.wrap{width:min(1320px,calc(100% - 32px));margin:0 auto}.top{background:#171719;color:#fff;border-bottom:4px solid var(--red)}.top .wrap{display:flex;align-items:center;justify-content:space-between;min-height:76px}.brand{font-size:22px;font-weight:900;letter-spacing:.04em}.brand span{color:var(--red)}.secure{font-size:13px;color:#c8c8cc}.card{background:#fff;border:1px solid var(--line);border-radius:18px;box-shadow:0 8px 30px rgba(0,0,0,.06)}main.wrap{padding:30px 0 60px}.hero,.section,.summary{padding:24px}.hero{margin-bottom:20px}.eyebrow{font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:var(--red)}h1{font-size:clamp(25px,4vw,40px);line-height:1.1;margin:8px 0 12px}h2{margin:0 0 18px;font-size:21px}.meta{display:flex;gap:10px 24px;flex-wrap:wrap;color:var(--muted)}.status{display:inline-flex;padding:6px 11px;border-radius:999px;background:#fff1f1;color:var(--red-dark);font-size:13px;font-weight:800}.grid{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:20px}.section{margin-bottom:20px}.item{display:grid;grid-template-columns:72px minmax(230px,1.6fr) repeat(3,minmax(110px,.7fr));gap:14px;padding:18px 0;border-top:1px solid var(--line);align-items:start}.item:first-of-type{border-top:0;padding-top:0}.item-image{width:72px;height:72px;object-fit:contain;border-radius:10px;border:1px solid var(--line);background:#fff}.item h3{margin:0 0 4px;font-size:16px}.sku,.small,.muted{font-size:13px;color:var(--muted)}.cell-title{font-size:11px;font-weight:800;text-transform:uppercase;color:var(--muted);margin-bottom:4px}.money{white-space:nowrap;font-weight:800}.summary{position:sticky;top:16px}.sum-row{display:flex;justify-content:space-between;gap:16px;padding:8px 0}.total{margin-top:10px;padding-top:14px;border-top:2px solid var(--red);font-size:20px;font-weight:900}.notice{padding:14px 16px;border-radius:11px;margin-bottom:18px;background:#e9f8ef;color:var(--ok)}.notice.error{background:#fff1f1;color:#9b2424}.button{display:inline-flex;align-items:center;justify-content:center;width:100%;border:0;border-radius:11px;padding:13px 16px;margin-top:10px;background:var(--red);color:#fff;text-decoration:none;font:inherit;font-weight:800;cursor:pointer}.button:hover{background:var(--red-dark)}.button.success{background:var(--ok)}.button.success:hover{background:#0e6337}.workflow{margin-top:18px;padding-top:18px;border-top:1px solid var(--line)}.workflow h3{margin:0 0 8px}.history{margin:14px 0 0;padding:0;list-style:none}.history li{padding:9px 0;border-top:1px solid var(--line);font-size:13px}.center{max-width:600px;margin:7vh auto;padding:32px;text-align:center}.center p{color:var(--muted)}.code,input[type=text]{width:100%;border:1px solid #cfd2d7;border-radius:9px;padding:11px;margin-top:10px;font:inherit}.code{font-size:28px;text-align:center;letter-spacing:.3em}.footer{padding:24px 0;text-align:center;color:var(--muted);font-size:13px}
        @media(max-width:980px){.grid{grid-template-columns:1fr}.summary{position:static}.item{grid-template-columns:64px minmax(0,1fr)}.item-image{width:64px;height:64px}.item>div:nth-child(n+3){grid-column:2}.secure{display:none}.wrap{width:min(100% - 20px,1320px)}.hero,.section,.summary{padding:18px}}
    </style>
</head>
<body>
<header class="top"><div class="wrap"><div class="brand">KOTLOV<span>.BY</span></div><div class="secure">Защищённый онлайн-заказ</div></div></header>
<main class="wrap">@yield('content')</main>
<footer class="footer">KOTLOV.BY · Заказ и контроль закупки</footer>
</body>
</html>
